go.solution:
package main

import (
	"bufio"
	"fmt"
	"os"
)

func greet(name string) {
	fmt.Printf("Hello, %s!\n", name)
}

func main() {
	scanner := bufio.NewScanner(os.Stdin)
	scanner.Scan()
	greet(scanner.Text())
}
